import type { CSSProperties, HTMLAttributes, ReactNode, Ref } from "react";
import "./Band.css";

// Band (Component) — a page section on its own ground: the tint runs edge to edge of the page frame
// while the content stays on the page's column. Category B: a painted region with no behaviour, so
// plain elements and no React Aria. It is the filled counterpart of `Separator variant="band"`, which
// parts two sections with a strip; a Band IS the section.
//
// `tone="inverse"` puts the section on an INVERSE GROUND: it sets `data-ground="inverse"`, and the token
// build re-declares every colour role inside it at the opposite theme's value (a light page's band goes
// dark, a dark page's goes light). Everything inside, the band's own paint included, then resolves there,
// so nothing in it needs an inverse variant of its own.
export interface BandProps extends Omit<HTMLAttributes<HTMLElement>, "className" | "style"> {
  /** The element the section renders as. A labelled `section` is a region landmark. @default "section" */
  as?: "section" | "div" | "aside";
  /** The section's ground. `inverse` turns the band and everything in it to the opposite theme, the
   *  way a page-closing footer sits dark on a light page. @default "neutral" */
  tone?: "neutral" | "inverse";
  /** The section's content, laid out on the page's column. */
  children?: ReactNode;
  /** Additional class. sd-band is always retained. */
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export function Band({ as: Element = "section", tone = "neutral", children, className, style, ref, ...props }: BandProps) {
  return (
    <Element
      {...props}
      ref={ref as Ref<HTMLElement & HTMLDivElement>}
      style={style}
      data-ground={tone === "inverse" ? "inverse" : undefined}
      className={className ? `sd-band ${className}` : "sd-band"}
    >
      {children}
    </Element>
  );
}

/* Band — a page section painted edge to edge of its frame, its content kept on the page's column.
   One frame width (`100cqi`: the nearest inline-size container, which AppShell's panel declares; the
   viewport where there is none) pulled back by the difference between frame and column, then that same
   difference given back as inline padding, so the children start exactly where the column does.
   Centred content is assumed, which a page's sections are (Separator `band` makes the same assumption).
   On an inverse ground (`tone="inverse"`) the same paint resolves to the opposite theme's value, because
   the token build re-declares the band's background token inside the ground; no second rule is needed. */
.sd-band {
  width: 100cqi;
  margin-inline-start: calc(50% - 50cqi);
  padding-inline: calc(50cqi - 50%);
  padding-block: var(--sd-band-padding-block);
  background: var(--sd-band-background);
}
